## Spring Boot build.gradle.kts (Kotlin DSL)

```kotlin
// build.gradle.kts
plugins {
    id("org.springframework.boot") version "3.2.5"
    id("io.spring.dependency-management") version "1.1.5"
    kotlin("jvm") version "1.9.23"  // if using Kotlin
    java  // for Java projects
}

group = "com.mycompany"
version = "1.0.0-SNAPSHOT"
java.sourceCompatibility = JavaVersion.VERSION_21

repositories {
    mavenCentral()
}

dependencies {
    implementation("org.springframework.boot:spring-boot-starter-web")
    implementation("org.springframework.boot:spring-boot-starter-data-jpa")
    runtimeOnly("org.postgresql:postgresql")
    testImplementation("org.springframework.boot:spring-boot-starter-test")
    testImplementation("org.testcontainers:postgresql")
    // No versions needed — managed by spring-dependency-management plugin
}

tasks.withType<Test> {
    useJUnitPlatform()
}

// Custom task example
tasks.register("buildDocker") {
    dependsOn("bootJar")
    doLast {
        exec {
            commandLine("docker", "build", "-t", "myapp:${version}", ".")
        }
    }
}
```

## Gradle Build Performance Features

```kotlin
// gradle.properties — enable performance features
org.gradle.daemon=true          // reuse JVM across builds
org.gradle.caching=true         // cache task outputs
org.gradle.parallel=true        // build independent modules in parallel
org.gradle.jvmargs=-Xmx2g      // give Gradle daemon more memory

// Incremental compilation:
// Gradle tracks which classes changed → recompiles only affected classes
// In a 500-class project, changing one file compiles ~5-10 classes, not 500
```

## Gradle vs Maven Comparison

| Feature | Gradle | Maven |
|---------|--------|-------|
| Config format | Kotlin/Groovy DSL | XML |
| Flexibility | High | Limited |
| Learning curve | Steeper | Gentler |
| Build speed | Faster (incremental, cache) | Slower |
| Ecosystem maturity | Good | Excellent |
| IDE support | Excellent | Excellent |
| Android support | Yes (only option) | No |
| Convention | Flexible | Strict |

## Key Gradle Commands

```bash
./gradlew build          # compile + test + JAR
./gradlew test           # run tests only
./gradlew bootRun        # run Spring Boot app
./gradlew dependencies   # show dependency tree
./gradlew tasks          # list available tasks
./gradlew build --build-cache  # use build cache
./gradlew :order-service:build  # build specific subproject
```

## Multi-Project Structure

```
my-backend/
├── settings.gradle.kts       ← declares all subprojects
├── build.gradle.kts          ← root build config
├── buildSrc/                 ← convention plugins
│   ├── build.gradle.kts
│   └── src/main/kotlin/
│       └── java-conventions.gradle.kts
├── common/
│   ├── build.gradle.kts
│   └── src/
├── order-service/
│   ├── build.gradle.kts
│   └── src/
└── payment-service/
    ├── build.gradle.kts
    └── src/
```

## settings.gradle.kts

```kotlin
rootProject.name = "my-backend"

include(
    "common",
    "order-service",
    "payment-service"
)

// Enable build cache
buildCache {
    local { isEnabled = true }
    // remote cache: uncomment for CI sharing
    // remote<HttpBuildCache> {
    //     url = uri("https://build-cache.mycompany.com/cache/")
    // }
}
```

## Convention Plugin (buildSrc)

```kotlin
// buildSrc/src/main/kotlin/java-conventions.gradle.kts
// Applied by all subprojects — single source of truth for build config

plugins {
    java
    id("org.springframework.boot")
    id("io.spring.dependency-management")
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}

tasks.withType<Test> {
    useJUnitPlatform()
    testLogging { events("passed", "skipped", "failed") }
}

dependencies {
    testImplementation("org.springframework.boot:spring-boot-starter-test")
}
```

## Subproject build.gradle.kts

```kotlin
// order-service/build.gradle.kts
plugins {
    id("java-conventions")  // apply the convention plugin
}

dependencies {
    implementation(project(":common"))  // sibling module
    implementation("org.springframework.boot:spring-boot-starter-web")
    runtimeOnly("org.postgresql:postgresql")
}
```

## Version Catalog (gradle/libs.versions.toml)

```toml
[versions]
spring-boot = "3.2.5"
java = "21"
jackson = "2.16.1"
testcontainers = "1.19.7"

[libraries]
spring-boot-web      = { module = "org.springframework.boot:spring-boot-starter-web",      version.ref = "spring-boot" }
spring-boot-jpa      = { module = "org.springframework.boot:spring-boot-starter-data-jpa", version.ref = "spring-boot" }
spring-boot-test     = { module = "org.springframework.boot:spring-boot-starter-test",     version.ref = "spring-boot" }
spring-boot-security = { module = "org.springframework.boot:spring-boot-starter-security", version.ref = "spring-boot" }

jackson-databind     = { module = "com.fasterxml.jackson.core:jackson-databind",            version.ref = "jackson" }
postgresql-driver    = { module = "org.postgresql:postgresql" }  # version from Spring BOM

testcontainers-core  = { module = "org.testcontainers:testcontainers",  version.ref = "testcontainers" }
testcontainers-pg    = { module = "org.testcontainers:postgresql",       version.ref = "testcontainers" }

[bundles]
testing = ["spring-boot-test", "testcontainers-core", "testcontainers-pg"]

[plugins]
spring-boot         = { id = "org.springframework.boot",   version.ref = "spring-boot" }
dependency-mgmt     = { id = "io.spring.dependency-management", version = "1.1.5" }
```

## Using Version Catalog in build.gradle.kts

```kotlin
plugins {
    alias(libs.plugins.spring.boot)
    alias(libs.plugins.dependency.mgmt)
    java
}

dependencies {
    implementation(libs.spring.boot.web)
    implementation(libs.spring.boot.jpa)
    implementation(libs.spring.boot.security)
    runtimeOnly(libs.postgresql.driver)

    // Bundle: adds all test dependencies at once
    testImplementation(libs.bundles.testing)
}

// BOM import: aligns transitive dependency versions
dependencies {
    implementation(platform(libs.spring.boot.web))  // imports Spring Boot BOM
}
```

## Integration Test Source Set

```kotlin
// build.gradle.kts
val integrationTest by sourceSets.creating {
    compileClasspath += sourceSets.main.get().output
    runtimeClasspath += sourceSets.main.get().output
}

configurations[integrationTest.implementationConfigurationName].extendsFrom(
    configurations.testImplementation.get()
)
configurations[integrationTest.runtimeOnlyConfigurationName].extendsFrom(
    configurations.testRuntimeOnly.get()
)

val integrationTestTask = tasks.register<Test>("integrationTest") {
    description = "Runs integration tests"
    group = "verification"
    testClassesDirs = integrationTest.output.classesDirs
    classpath = integrationTest.runtimeClasspath
    shouldRunAfter(tasks.test)
    useJUnitPlatform()
}

tasks.check { dependsOn(integrationTestTask) }
```

## Test Configuration

```kotlin
tasks.withType<Test> {
    useJUnitPlatform()  // enable JUnit 5

    // Parallel test execution
    maxParallelForks = (Runtime.getRuntime().availableProcessors() / 2).coerceAtLeast(1)

    // Log test results
    testLogging {
        events("passed", "skipped", "failed")
        exceptionFormat = TestExceptionFormat.FULL
        showStandardStreams = false
    }

    // JVM args for tests
    jvmArgs("-XX:+UseContainerSupport", "-Xmx512m")

    // System properties for tests
    systemProperty("spring.profiles.active", "test")

    // Fail fast: stop on first test failure
    failFast = false  // true for faster CI feedback
}

// Jacoco coverage after unit tests
tasks.test {
    finalizedBy(tasks.jacocoTestReport)
}
```

## Custom Task Examples

```kotlin
// build.gradle.kts

// Simple task: print project info
tasks.register("projectInfo") {
    group = "help"
    description = "Print project version and Git info"
    doLast {
        println("Project: ${project.name} v${project.version}")
        exec { commandLine("git", "log", "-1", "--format=%h %s") }
    }
}

// Exec task: build and push Docker image after JAR is built
tasks.register<Exec>("buildDockerImage") {
    group = "docker"
    description = "Build Docker image tagged with version"
    dependsOn(tasks.bootJar)  // JAR must be built first

    inputs.files(tasks.bootJar.get().outputs.files)  // re-run if JAR changes
    inputs.file("Dockerfile")                        // re-run if Dockerfile changes

    val imageTag = "${project.name}:${project.version}"
    commandLine("docker", "build", "-t", imageTag, ".")

    doLast { println("Built Docker image: $imageTag") }
}

tasks.register<Exec>("pushDockerImage") {
    group = "docker"
    dependsOn("buildDockerImage")
    val imageTag = "my-registry.io/${project.name}:${project.version}"
    commandLine("docker", "push", imageTag)
}

// Copy task: copy config files to build output
tasks.register<Copy>("copyConfig") {
    from("src/main/config") { include("*.yml") }
    into("${layout.buildDirectory.get()}/resources/main")
    // Up-to-date if config files haven't changed
}

// Chain: full CI build
tasks.register("ciBuild") {
    group = "ci"
    dependsOn(tasks.build, "buildDockerImage")
    doLast { println("CI build complete") }
}
```

```bash
# List all tasks
./gradlew tasks --group docker

# Run custom task
./gradlew buildDockerImage
./gradlew ciBuild
```
